/**
 * API Response Helper Node for Node-RED
 * Makes it easier to send responses back to API Endpoint nodes
 */

module.exports = function(RED) {
    "use strict";

    function APIResponseNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        
        node.statusCode = n.statusCode || 200;
        node.headers = n.headers || {};

        node.on("input", function(msg, send, done) {
            // Check if this message came from an API endpoint
            if (!msg._httpReq || !msg._httpRes) {
                node.error("Message did not originate from an API endpoint", msg);
                if (done) done();
                return;
            }

            // Set response properties
            msg._isResponse = true;
            
            // Use configured status code if not already set
            if (!msg.statusCode) {
                msg.statusCode = node.statusCode;
            }
            
            // Merge configured headers
            if (!msg.headers) {
                msg.headers = {};
            }
            for (const [key, value] of Object.entries(node.headers)) {
                if (!msg.headers[key]) {
                    msg.headers[key] = value;
                }
            }
            
            // Set default content type if not specified
            if (!msg.headers['Content-Type']) {
                msg.headers['Content-Type'] = 'application/json';
            }

            node.status({fill: "green", shape: "dot", text: `${msg.statusCode} response`});
            
            // Send back to the API endpoint for response handling
            send(msg);
            if (done) done();
        });

        node.on("close", function() {
            node.status({});
        });
    }

    RED.nodes.registerType("api-response", APIResponseNode);
}; 